window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"7GzI0WnMPWA","speaker":"Micheál Martin","role":"Taoiseach","country":"Ireland","region":"Europe","url":"https://www.youtube.com/watch?v=7GzI0WnMPWA","date":"20260925","title":"🇮🇪 Ireland - Taoiseach Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1061,"words":2343,"counts":{"claims":34,"promises":3,"attacks":4},"topics":[{"topic":"UN reform","share":0.2854,"seconds":303},{"topic":"Israel-Gaza","share":0.2383,"seconds":253},{"topic":"Russia-Ukraine","share":0.1232,"seconds":131},{"topic":"Sudan","share":0.1192,"seconds":126},{"topic":"Afghanistan","share":0.1173,"seconds":124},{"topic":"Iran","share":0.06,"seconds":64},{"topic":"Climate change","share":0.0566,"seconds":60}],"timeline":[[3,68,"UN reform"],[69,134,"UN reform"],[135,199,"UN reform"],[201,264,"Afghanistan"],[265,326,"Afghanistan"],[327,390,"Russia-Ukraine"],[391,459,"Russia-Ukraine"],[461,525,"Sudan"],[526,588,"Sudan"],[589,651,"Israel-Gaza"],[652,715,"Israel-Gaza"],[716,779,"Israel-Gaza"],[780,845,"Israel-Gaza"],[847,910,"Iran"],[911,975,"UN reform"],[976,1037,"Climate change"],[1038,1083,"UN reform"]],"stances":{"UN reform":"Micheál Martin states that the UN is facing uncertainty, conflicts, climate crisis impacts, human rights rollbacks, and strain on the international legal order.","Afghanistan":"Micheál Martin states that the systematic exclusion of women and girls in Afghanistan is a defining challenge requiring international action rather than passive observation.","Russia-Ukraine":"Micheál Martin states that Russia's war in Ukraine is increasingly deadly for civilians and refuses to halt its attacks, while noting the global economic impact on food costs.","Sudan":"Micheál Martin calls for an end to external interference and arms supply in Sudan while highlighting the displacement of its people.","Israel-Gaza":"Micheál Martin states that the international community has failed Palestine, calls for a two-state solution where Israel and Palestine live side by side in peace, and notes progress in recognizing Palestine while opposing illegal settlement occupation.","Iran":"Micheál Martin states that Iran must never possess a nuclear weapon and calls for dialogue to achieve a negotiated settlement.","Climate change":"Micheál Martin commends Secretary General Antonio Guterres for his leadership on the climate crisis and highlights the importance of international cooperation through the Paris Agreement."},"claims":[{"t":37,"quote":"The United Nations is entering its ninth decade at a moment of great uncertainty and challenge for the global community.","topic":"UN reform","kind":"fact"},{"t":45,"quote":"Conflicts are having devastating effects on the most vulnerable.","topic":"UN reform","kind":"fact"},{"t":49,"quote":"The impacts of the climate crisis are felt in every corner of our world.","topic":"UN reform","kind":"fact"},{"t":54,"quote":"Hard one rights are being rolled back.","topic":"UN reform","kind":"fact"},{"t":69,"quote":"New and emerging technologies that offer unlimited potential could also without human intervention create unprecedented dangers.","topic":"UN reform","kind":"fact"},{"t":135,"quote":"The multilateral system anchored in the United Nations charter has been the foundation of many of humanity's greatest achievements.","topic":"UN reform","kind":"fact"},{"t":144,"quote":"It has driven advances in poverty alleviation, health care, education, social protection, and food and nutrition security.","topic":"UN reform","kind":"fact"},{"t":174,"quote":"Ireland currently holds the presidency of the Council of the European Union.","topic":"UN reform","kind":"fact"},{"t":249,"quote":"The situation in Afghanistan is one of the clearest examples of this.","topic":"Afghanistan","kind":"fact"},{"t":254,"quote":"The systematic exclusion of women and girls from education, employment, and public life is not something that the international community can simply observe from a distance.","topic":"Afghanistan","kind":"fact"},{"t":268,"quote":"Girls are being denied the education that should shape their futures. Women are being denied the ability to work, to participate fully in society and to contribute to the economic and social life of their country.","topic":"Afghanistan","kind":"fact"},{"t":301,"quote":"Across the world, women and girls face conflict related sexual violence, force displacement, trafficking, and discrimination. Across the world, LGBTQI plus people face growing threats to their rights, safety, and dignity.","topic":"Afghanistan","kind":"fact"},{"t":384,"quote":"This time last year, a bushel of wheat was just over $5. This year, it's more than $7.","topic":"Russia-Ukraine","kind":"number"},{"t":391,"quote":"The fact that a permanent member of the security council is seeking to change bo borders by force in clear violation of the UN charter is utterly unacceptable.","topic":"Russia-Ukraine","kind":"fact"},{"t":420,"quote":"Ireland stands in solidarity with Ukraine and will continue to do so.","topic":"Russia-Ukraine","kind":"self_credit"},{"t":522,"quote":"15 million Sudi Sudin people are displaced from their homes.","topic":"Sudan","kind":"number"},{"t":526,"quote":"Over 19 and a half million face crisis levels of hunger. 33 million need urgent humanitarian assistance.","topic":"Sudan","kind":"number"},{"t":536,"quote":"Violations of international law, including targeting on the basis of ethnicity, deliberate destruction of the means of survival, killing, torture, and sexual violence are again being used as weapons of war.","topic":"Sudan","kind":"fact"},{"t":594,"quote":"The peace plan on Gaza agreed last October was welcome, but it has not fundamentally changed the reality on the Israeli strikes continue. Humanitarian aid remains blocked. Civilians continue to suffer.","topic":"Israel-Gaza","kind":"fact"},{"t":609,"quote":"We, the collected international community, have failed Palestine.","topic":"Israel-Gaza","kind":"fact"},{"t":635,"quote":"More countries have recognized the state of Palestine.","topic":"Israel-Gaza","kind":"number"},{"t":672,"quote":"We are going to fulfill our promise that there will be no Palestinian state. This place belongs to us.","topic":"Israel-Gaza","kind":"fact"},{"t":699,"quote":"Where eight children died because one of them collapsed.","topic":"Israel-Gaza","kind":"number"},{"t":742,"quote":"In the West Bank, the relentless expansion of settlements have reached the scale without precedent","topic":"Israel-Gaza","kind":"fact"},{"t":754,"quote":"Violent settlers continue to act with near total impunity while Palestinian communities face a sustained campaign of displacement and destruction amounting to ethnic cleansing","topic":"Israel-Gaza","kind":"fact"},{"t":780,"quote":"The United Nations reports that this year there have been almost 200 attacks against Palestinians every month.","topic":"Israel-Gaza","kind":"number"},{"t":795,"quote":"The International Court of Justice has been clear. Settlements in occupied Palestinian territory are illegal.","topic":"Israel-Gaza","kind":"fact"},{"t":862,"quote":"since 1978, Irish soldiers have served with distinction in Lebanon in the unif peacekeeping operation","topic":"Iran","kind":"fact"},{"t":879,"quote":"We have consistently condemned Hezbollah's attacks on Israel","topic":"Iran","kind":"fact"},{"t":955,"quote":"Too long, the veto has stmmied the council and eroded its legitimacy.","topic":"UN reform","kind":"fact"},{"t":967,"quote":"starting with the historic underrepresentation of African countries","topic":"UN reform","kind":"fact"},{"t":995,"quote":"From devastating floods in Nepal to wildfires across Europe, communities are increasingly experiencing the consequences of a ch a changing climate.","topic":"Climate change","kind":"fact"},{"t":1006,"quote":"The Paris Agreement remains a powerful example of what can be achieved when countries work together.","topic":"Climate change","kind":"fact"},{"t":1038,"quote":"The United Nations, for all its imperfections, remains one of humanity's greatest achievements, a testament to the belief that peace, dignity, and progress are best secured when nations work together.","topic":"UN reform","kind":"fact"}],"promises":[{"t":339,"quote":"if elected, we will use that seat to defend the principle that human rights belong to everyone everywhere.","topic":"Russia-Ukraine","kind":"promise"},{"t":425,"quote":"We will continue to support efforts to hold Russia accountable for its actions.","topic":"Russia-Ukraine","kind":"promise"},{"t":870,"quote":"Ireland will continue to work with Lebanon, European Union, and international partners to support Lebanon's future peace","topic":"Iran","kind":"promise"}],"attacks":[{"t":359,"quote":"Russia's reckless drone and missile attacks on Ukrainian towns and cities continue to intensify.","topic":"Russia-Ukraine","target":"Russia"},{"t":366,"quote":"These are not the actions of a country interested in peace.","topic":"Russia-Ukraine","target":"Russia"},{"t":391,"quote":"The fact that a permanent member of the security council is seeking to change bo borders by force in clear violation of the UN charter is utterly unacceptable.","topic":"Russia-Ukraine","target":"Russia"},{"t":678,"quote":"As he permitted the E1 illegal development in East Jerusalem, and the situation in Gaza remains an affront to all that is decent.","topic":"Israel-Gaza","target":"Israel"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"UN reform","text":"The assembly will hear an address by his excellency Mihal Martin Tishuk of Ireland. I request protocol to escort his excellency and invite him to address the assembly. President of the General Assembly. Distinguished Heads of State and Government, Secretary General, Excellency Accord, Friends, the United Nations is entering its ninth decade at a moment of great uncertainty and challenge for the global community. Conflicts are having devastating effects on the most vulnerable. The impacts of the climate crisis are felt in every corner of our world. Hard one rights are being rolled back. narrow self-interest is breaking the bonds of solidarity which have so often lifted us to meaningful progress. The international legal order is under tremendous strain."},{"t":69,"topic":"UN reform","text":"New and emerging technologies that offer unlimited potential could also without human intervention create unprecedented dangers. In such moments of uncertainty, it can be easy to question our foundations, to retreat, to turn inward, to say that international cooperation is too difficult, that multilateralism does not work, that the problems of others are not our problems. But that would be the wrong conclusion because the answer to a world under strain is not less international cooperation. It is more. The answer to the weakening of principles is not to abandon them. It is to defend them. And if our multilateral system is not working effectively, the answer is not to walk away from it. It is to make it stronger, fairer, and fit for the world we live in. That is Ireland's position and that is what all of us as members of the United Nations need to deliver on. We should also remember what our collective commitment to the United Nations has achieved."},{"t":135,"topic":"UN reform","text":"The multilateral system anchored in the United Nations charter has been the foundation of many of humanity's greatest achievements. It has driven advances in poverty alleviation, health care, education, social protection, and food and nutrition security. It has championed human rights and dignity and insisted that accountability matters. It has given voice to the marginalized. Mr. President, the people of Ireland understand that we live in an interdependent world, that the challenges we face are interconnected, cross borders, and require collective Ireland currently holds the presidency of the Council of the European Union. Our stewardship of the European Union's agenda is deeply rooted in the principle of strength with unity. And this principle is at the heart of our vision for the United Nations. as well as our unwavering commitment to the pillars which guide its work, peace and security, human rights and development."},{"t":201,"topic":"Afghanistan","text":"These pillars equally bear the weight of our shared ambition for a better, fairer and peaceful world. Collectively, however, we are not delivering on their ambition. We are not staying the course. At a time when global needs are increasing and becoming more complex, our responsibility to act does not diminish. Mr. President, the denial of the fundamental human rights of millions of people around the world remains one of the defining challenges of our time. Renewed pressure on women's rights and gender equality is putting hard one progress at risk. Women and girls are being told that their ambitions, their education, their voices, and their very presence in public life are unacceptable. The situation in Afghanistan is one of the clearest examples of this. The systematic exclusion of women and girls from education, employment, and public life is not something that the international community can simply observe from a distance."},{"t":265,"topic":"Afghanistan","text":"It is a profound human rights crisis. Girls are being denied the education that should shape their futures. Women are being denied the ability to work, to participate fully in society and to contribute to the economic and social life of their country. Their freedoms are being progressively erased and the world must not become inured to it. We must not allow the absence of headlines to become an absence of action. The women of Afghanistan have not disappeared and neither should our solidarity. The same is true elsewhere. Across the world, women and girls face conflict related sexual violence, force displacement, trafficking, and discrimination. Across the world, LGBTQI plus people face growing threats to their rights, safety, and dignity. Ireland remains firmly committed to the universality, indivisibility, and equal application of human rights."},{"t":327,"topic":"Russia-Ukraine","text":"These principles are beyond question. That commitment is why Ireland is seeking election to the human rights council for the 2027 2029 term. And if elected, we will use that seat to defend the principle that human rights belong to everyone everywhere. Mr. President, today's Russia's legal today today Russia's legal war in Ukraine is more deadly for civilians than at any point since the start of their full-scale invasion. Russia's reckless drone and missile attacks on Ukrainian towns and cities continue to intensify. These are not the actions of a country interested in peace. Russia could halt its brutal attacks at any time. Yet, it refuses to do so. Russia's actions have already had direct global impact in increased food and energy costs. This time last year, a bushel of wheat was just over $5. This year, it's more than $7."},{"t":391,"topic":"Russia-Ukraine","text":"The fact that a permanent member of the security council is seeking to change bo borders by force in clear violation of the UN charter is utterly unacceptable. Sovereignty and territorial integrity apply equally to all states. The international community must remain steadfast in our response in support of the UN charter and of a comprehensive, just and lasting peace. Ireland stands in solidarity with Ukraine and will continue to do so. We will continue to support efforts to hold Russia accountable for its actions. There can be no impunity for war crimes. Not in Ukraine, not anywhere. And that is why Ireland is a steadfast supporter of the International Criminal Court. Ireland strongly opposes efforts to undermine the court. All measures against it should be immediately withdrawn. The international legal order founded on our agreements to make the world a safer and more secure place is being challenged."},{"t":461,"topic":"Sudan","text":"International law represents the collective lessons drawn from conflict, suffering, and atrocity. The rules and institutions that we have built over generations exist to protect the rights, security, and sovereignty of all states and all peoples. When these principles are disregarded, the consequences extend far beyond any single conflict. We all become less Mr. President, 20 years ago, the Commission on War crimes and crimes against humanity in Darur saw the international community come together to fulfill our collective responsibility to protect. Despite the extraordinary efforts of the Sudin people, the cycle of violence has continued. The conflict has been inflamed and prolonged by harmful outside interference. All states and external actors must cease arming, financing, and enabling the war in Sudan. 15 million Sudi Sudin people are displaced from their homes."},{"t":526,"topic":"Sudan","text":"Over 19 and a half million face crisis levels of hunger. 33 million need urgent humanitarian assistance. Violations of international law, including targeting on the basis of ethnicity, deliberate destruction of the means of survival, killing, torture, and sexual violence are again being used as weapons of war. We need to act decisively to support the people of Sudan to end this conflict. We must support their aspirations for democracy, justice, and development. Sudan has become a forgotten war despite its devastating impacts. We must not allow the absence of daily headlines to become a license for inaction. The people of Sudan deserve the same attention, urgency, and solidarity that we rightly extend to crises elsewhere. Mr. President, despite its prevalence, we cannot ever allow ourselves to become indifferent to conflict and the human suffering it brings."},{"t":589,"topic":"Israel-Gaza","text":"To do so would deny the shared humanity of its victims. The peace plan on Gaza agreed last October was welcome, but it has not fundamentally changed the reality on the Israeli strikes continue. Humanitarian aid remains blocked. Civilians continue to suffer. We, the collected international community, have failed Palestine. Ireland, like most gathered here, believe that the only viable solution to the decades of conflict, misery, and wasted human lives, is a situation where a state of Palestine and a state of Israel live side by side in peace, security, and dignity. There are modest signs of progress. More countries have recognized the state of Palestine. An overwhelming majority of UN member states has endorsed the New York More of us have taken steps to push back against the illegal and violent settler occupation of Palestinian land in the West Bank."},{"t":652,"topic":"Israel-Gaza","text":"But time is running out. What we are witnessing on the ground is a deliberate attempt by some to make the prospect of a two-state solution This is not some mad conspiracy theory. It is the stated intent of the prime minister of Israel who said clearly that and I quote, \"We are going to fulfill our promise that there will be no Palestinian state. This place belongs to us.\" As he permitted the E1 illegal development in East Jerusalem, and the situation in Gaza remains an affront to all that is decent. How can we tolerate a situation where civilians are so desperate for shelter that that they have to make their homes in war damaged and unsafe buildings? Where eight children died because one of them collapsed. Where the most basic humanitarian aid, food and shelter is deliberately impeded. When the full truth of what has happened, what is still happening in Gaza is finally known."},{"t":716,"topic":"Israel-Gaza","text":"When the evidence is gathered, when the testimonies are heard, when the true horrors are finally and fully revealed, it will shame the world. Nobody will be able to say that we did not know. Let it not be said that we did not act. in the West Bank. In the West Bank, the relentless expansion of settlements have reached the scale without precedent, further eroding, eroding the prospects for a just and lasting peace. Violent settlers continue to act with near total impunity while Palestinian communities face a sustained campaign of displacement and destruction amounting to ethnic cleansing. Entire villages have been raised, homes and vital infrastructure demolished and thousands of Palestinian families driven from the places they have called home for generations and exposed to intimidation and violence."},{"t":780,"topic":"Israel-Gaza","text":"The United Nations reports that this year there have been almost 200 attacks against Palestinians every month. A stark reminder of a reality that is deepening conflict, suffering, and despair. The International Court of Justice has been clear. Settlements in occupied Palestinian territory are illegal. Ireland has acted alongside others to prohibit the import of settlement goods. It is never too late to uphold international law. Mr. President, the conflict in the Gulf remains deeply concerning and is having a serious impact around the world. We need to get back to meaningful goodfaith negotiations by all sides. Ireland has consistently stated that Iran must cease its attacks on its neighbors and also end its destabilizing activities across the region, including strikes on ships in the Strait of Hermuz. Vessels must be allowed to transit the strait safely and without tolls in line with international law."},{"t":847,"topic":"Iran","text":"If we are to build greater stability, Iran must never have a nuclear weapon. Iran's destabilizing influence across the region must cease. We need dialogue to achieve a negotiated settlement. Mr. President, since 1978, Irish soldiers have served with distinction in Lebanon in the unif peacekeeping operation. Ireland will continue to work with Lebanon, European Union, and international partners to support Lebanon's future peace and We have consistently condemned Hezbollah's attacks on Israel, which must cease immediately. Israel must withdraw its military presence from southern Lebanon and bring an end to its military operations there. Israel's response has been wholly We honor the courage, professionalism, and dedication of all peacekeepers who have served under the United Nations. We remember with particular respect those who lost their lives in the cause of peace."},{"t":911,"topic":"UN reform","text":"We welcome the Secretary General's report on the future of peacekeeping and Ireland will work with others to ensure that this essential capacity adapts to the 21st century. Ireland also welcomes wider reforms in efforts in the United Nations system. These are necessary if we are to meet the challenges of our rapidly changing world. But it is it is also necessary to point out that no reform process can succeed unless member states are prepared to support the United Nations politically, financially and through their actions. We need the security council to live up to its mandate and respond to the crisis around us. Too long, the veto has stmmied the council and eroded its legitimacy. The council's membership must also finally be made representative of the world we live in, starting with the historic underrepresentation of African countries and ensuring that the voices of small and the most vulnerable states are heard."},{"t":976,"topic":"Climate change","text":"Mr. President, I conclude by thanking Secretary General Antonio Gutierrez for his principal leadership and steadfast commitment to the United Nations over the past decade. I especially commend his courage in tackling the climate crisis, the fundamental issue of our time. From devastating floods in Nepal to wildfires across Europe, communities are increasingly experiencing the consequences of a ch a changing climate. The Paris Agreement remains a powerful example of what can be achieved when countries work together. Secretary Gutierz has been a vital voice in calling member states to action. We look forward to working with the next Secretary General in advancing the charter's principles and strengthening this institution. As the leader of a country that fought for its independence and its place among nations, I'm deeply conscious conscious of the inheritance we have received."},{"t":1038,"topic":"UN reform","text":"The United Nations, for all its imperfections, remains one of humanity's greatest achievements, a testament to the belief that peace, dignity, and progress are best secured when nations work together. At a time when that belief is under strain, it is our shared responsibility to renew it, strengthen it, and ensure it endures for generations to come. Thank you very much On behalf of the assembly, I wish to thank the teach of Ireland."}],"compare":[{"topic":"UN & its reform","share":0.2854,"mean":0.2043,"rank":52,"others":170},{"topic":"Israel–Palestine","share":0.2383,"mean":0.0514,"rank":8,"others":76},{"topic":"Russia-Ukraine War","share":0.1232,"mean":0.0349,"rank":19,"others":44},{"topic":"Sudan","share":0.1192,"mean":0.0067,"rank":3,"others":15},{"topic":"Afghanistan","share":0.1173,"mean":0.0012,"rank":1,"others":3},{"topic":"Iran","share":0.06,"mean":0.0135,"rank":23,"others":25},{"topic":"Climate Change","share":0.0566,"mean":0.0427,"rank":59,"others":77}]};
